import{_ as o,o as a,c as r,a6 as i}from"./chunks/framework.BfmC6wP_.js";const f=JSON.parse('{"title":"User docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/user-docs.md","filePath":"content/plugins/bcew-chefs-embed/user-docs.md"}'),t={name:"content/plugins/bcew-chefs-embed/user-docs.md"};function s(n,e,l,d,m,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="user-docs" tabindex="-1">User docs <a class="header-anchor" href="#user-docs" aria-label="Permalink to “User docs”">​</a></h1><p>This guide explains how site administrators can add and manage existing CHEFS forms for use in WordPress pages and posts.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to “Before you begin”">​</a></h2><p>Before configuring a form in WordPress, you will need:</p><ul><li>access to the CHEFS service</li><li>a Form ID from your form</li><li>an API key from your form</li></ul><h2 id="how-to-get-your-form-id-and-api-key-for-the-chefs-plugin" tabindex="-1">How to get your Form ID and API key for the CHEFS plugin <a class="header-anchor" href="#how-to-get-your-form-id-and-api-key-for-the-chefs-plugin" aria-label="Permalink to “How to get your Form ID and API key for the CHEFS plugin”">​</a></h2><p>Log in to the CHEFS service portal at <a href="https://submit.digital.gov.bc.ca/app" target="_blank" rel="noreferrer">https://submit.digital.gov.bc.ca/app</a>.</p><h3 id="get-your-form-id" tabindex="-1">Get your Form ID <a class="header-anchor" href="#get-your-form-id" aria-label="Permalink to “Get your Form ID”">​</a></h3><ol><li>Go to <strong>My Forms</strong> and select your form.</li><li>Click <strong>Manage</strong>, then click <strong>Share form</strong> in the top right.</li><li>Copy the Form ID from the URL. For example, in <code>https://submit.digital.gov.bc.ca/app/form/submit?f=43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>, the Form ID is <code>43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>.</li></ol><p>You can also copy the Form ID from the <code>f</code> value in the URL on the form&#39;s <strong>Manage</strong> page.</p><h3 id="get-your-api-key" tabindex="-1">Get your API key <a class="header-anchor" href="#get-your-api-key" aria-label="Permalink to “Get your API key”">​</a></h3><ol><li>Close the sharing popup, if it is open.</li><li>Expand the <strong>API Key</strong> accordion below the <strong>Form Settings</strong> accordion.</li><li>Click the <strong>Eye</strong> button to reveal the API key.</li><li>Click <strong>Copy</strong>.</li></ol><p>Return to WordPress Admin and enter the Form ID and API key in the new form entry.</p><h2 id="manage-forms-in-the-chefs-forms-options-page" tabindex="-1">Manage forms in the CHEFS Forms options page <a class="header-anchor" href="#manage-forms-in-the-chefs-forms-options-page" aria-label="Permalink to “Manage forms in the CHEFS Forms options page”">​</a></h2><p>Open WordPress Admin and go to CHEFS Forms.</p><h3 id="add-a-new-form" tabindex="-1">Add a new form <a class="header-anchor" href="#add-a-new-form" aria-label="Permalink to “Add a new form”">​</a></h3><ol><li>Enter a Form ID.</li><li>Enter the API Key for that form.</li><li>Click <strong>Save</strong>.</li></ol><p>After you save:</p><ul><li>The form is added to the Configured Forms list.</li><li>The Form ID becomes available in the CHEFS Form block options.</li></ul><p>The Configured Forms table includes:</p><ul><li>Form ID</li><li>Date added</li><li>Confirmation message</li><li>Actions: <ul><li>Remove form</li><li>Edit confirmation</li></ul></li></ul><p>Note: API keys are hidden for security reasons.</p><h3 id="remove-a-form" tabindex="-1">Remove a form <a class="header-anchor" href="#remove-a-form" aria-label="Permalink to “Remove a form”">​</a></h3><p>Click <strong>Remove form</strong> next to the form you want to remove.</p><p>After you remove a form:</p><ul><li>The saved Form ID and API key are removed.</li><li>The form is removed from block selection options.</li><li>The custom confirmation for that form is also removed.</li></ul><h3 id="update-a-form-id-or-api-key" tabindex="-1">Update a Form ID or API key <a class="header-anchor" href="#update-a-form-id-or-api-key" aria-label="Permalink to “Update a Form ID or API key”">​</a></h3><p>There is no in-place update for Form ID or API key.</p><p>To update credentials, delete the existing form and add it again with the new values.</p><h2 id="manage-confirmation-messages" tabindex="-1">Manage confirmation messages <a class="header-anchor" href="#manage-confirmation-messages" aria-label="Permalink to “Manage confirmation messages”">​</a></h2><ul><li>Add, edit, or remove a custom confirmation message for each configured form.</li><li>If no custom confirmation is set, a generic success message is used.</li><li>Deleting a form removes its custom confirmation.</li><li>Re-adding a form starts without a custom confirmation.</li></ul><h2 id="add-a-chefs-form-block-to-a-page-or-post" tabindex="-1">Add a CHEFS form block to a page or post <a class="header-anchor" href="#add-a-chefs-form-block-to-a-page-or-post" aria-label="Permalink to “Add a CHEFS form block to a page or post”">​</a></h2><ol><li>Open the page or post in the block editor.</li><li>Insert the CHEFS Form block.</li><li>In the block sidebar, choose a Form ID from the dropdown.</li><li>Publish or update the page.</li></ol><h2 id="block-options" tabindex="-1">Block options <a class="header-anchor" href="#block-options" aria-label="Permalink to “Block options”">​</a></h2><ul><li><strong>Form ID:</strong> Selects which saved CHEFS form to embed.</li><li>Available values come from the CHEFS Forms options page.</li><li>If no forms are saved, the block shows a message and a link to open CHEFS settings.</li><li>If a selected Form ID is deleted from settings, the block selection is cleared and must be set again.</li></ul>',35)])])}const p=o(t,[["render",s]]);export{f as __pageData,p as default};
